  private void loadPreferences(){byte[] data=null;try{data=profile.readArchivePreferences();if(data==null)return;try(var in=new DataInputStream(new ByteArrayInputStream(data))){if(in.readInt()!=1)throw new IOException("Archive UI schema");Path chosen=Path.of(Binary.text(in,4096));if(!chosen.isAbsolute())throw new IOException("Archive UI path");Mode saved=Mode.valueOf(Binary.text(in,16));Sort sorting=Sort.valueOf(Binary.text(in,16));double left=in.readDouble(),right=in.readDouble();Binary.end(in);if(!Double.isFinite(left)||!Double.isFinite(right)||left<.1||left>.4||right<left+.15||right>.85)throw new IOException("Archive UI proportions");location=chosen;storedMode=saved;storedSort=sorting;firstDivider=left;secondDivider=right;}}catch(Exception invalid){status.setText("Оформление архива восстановлено по умолчанию");}finally{if(data!=null)Arrays.fill(data,(byte)0);}}
