  private void chooseContainer(){
    InWindowDirectoryChooser picker=new InWindowDirectoryChooser();Path selected=picker.choose(stage,"Папка архива");if(selected==null)return;
    try{
      // Newly selected private data must never enter a browser-visible mount.
      Path chosen=selected.toRealPath(),browser=org.securemail.client.safeweb.SafeWebSessions.defaultRoot().toAbsolutePath().normalize();
      if(Files.exists(browser))browser=browser.toRealPath();
      if(chosen.startsWith(browser)||browser.startsWith(chosen))throw new IOException("Выберите каталог архива отдельно от Safe Web");
      if(System.getProperty("os.name","").equals("Linux"))org.securemail.client.safeweb.LinuxSafeWebSandbox.checkHiddenPaths(List.of(chosen));
      location=chosen;schedulePreferences();lockedPage();
    }catch(IOException invalid){status.setText(invalid.getMessage());}
  }

