    search.setPromptText("Поиск по архиву");HBox.setHgrow(search,Priority.ALWAYS);type.getItems().setAll("Все типы","letter","text","image","pdf","file","folder");type.setValue("Все типы");mode.getItems().setAll(Mode.values());mode.setValue(storedMode);sort.getItems().setAll(Sort.values());sort.setValue(storedSort);since.setPromptText("С даты");until.setPromptText("По дату");since.setPrefWidth(145);until.setPrefWidth(145);
    MenuButton more=new MenuButton("Ещё");
    CheckMenuItem starred=new CheckMenuItem("Избранное"),deleted=new CheckMenuItem("Корзина");starred.selectedProperty().bindBidirectional(favorites.selectedProperty());deleted.selectedProperty().bindBidirectional(trash.selectedProperty());starred.setOnAction(e->refresh());deleted.setOnAction(e->refresh());
