    FlowPane filters=new FlowPane(8,8,search,type,since,until);VBox header=new VBox(10,actions,filters,usage);browser.setTop(header);BorderPane.setMargin(header,new Insets(0,0,12,0));
    tree.setPrefWidth(180);tree.setMinWidth(120);tree.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{if(b!=null){folder=b.getValue().id();refresh();}});
    tree.setCellFactory(v->new TreeCell<>(){protected void updateItem(Folder f,boolean empty){super.updateItem(f,empty);setText(empty||f==null?null:f.name());} {setOnDragOver(e->{if(getItem()!=null&&e.getDragboard().hasString()){e.acceptTransferModes(TransferMode.MOVE);e.consume();}});setOnDragDropped(e->{String id=e.getDragboard().getString();Folder dest=getItem();if(dest!=null)move(id,dest.id());e.setDropCompleted(dest!=null);e.consume();});}});
    list.setPlaceholder(new Label("Здесь пока ничего нет"));list.setCellFactory(v->new ListCell<>(){protected void updateItem(ArchiveEntry e,boolean empty){super.updateItem(e,empty);setText(null);setGraphic(null);setContextMenu(null);if(empty||e==null)return;Label name=new Label((e.favorite()?"★ ":"")+(e.directory()?"▸ ":"")+e.name());name.setWrapText(true);Label detail=new Label(size(e.size())+" · "+date(e.addedAt())+(e.tags().isEmpty()?"":" · "+String.join(", ",e.tags())));detail.getStyleClass().add("muted");VBox row=new VBox(mode.getValue()==Mode.CARDS?8:3,name,detail);if(mode.getValue()==Mode.CARDS){row.getStyleClass().add("letter-card");row.setPadding(new Insets(12));}setGraphic(row);setContextMenu(menu(e));} {setOnDragDetected(e->{if(getItem()!=null){var content=new ClipboardContent();content.putString(getItem().id());startDragAndDrop(TransferMode.MOVE).setContent(content);e.consume();}});}});
    list.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{if(b!=null)selected(b);});table.getColumns().clear();TableColumn<ArchiveEntry,String> name=new TableColumn<>("Название"),bytes=new TableColumn<>("Размер"),added=new TableColumn<>("Добавлено"),tags=new TableColumn<>("Теги");name.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().name()));bytes.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(size(c.getValue().size())));added.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(date(c.getValue().addedAt())));tags.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(String.join(", ",c.getValue().tags())));table.getColumns().addAll(name,bytes,added,tags);table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);table.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{if(b!=null)selected(b);});table.setRowFactory(v->new TableRow<>(){protected void updateItem(ArchiveEntry e,boolean empty){super.updateItem(e,empty);setContextMenu(empty||e==null?null:menu(e));} {setOnDragDetected(e->{if(getItem()!=null){var content=new ClipboardContent();content.putString(getItem().id());startDragAndDrop(TransferMode.MOVE).setContent(content);e.consume();}});}});
    mode.setOnAction(e->{arrange();list.refresh();schedulePreferences();});sort.setOnAction(e->{schedulePreferences();refresh();});query.setOnFinished(e->refresh());search.textProperty().addListener((o,a,b)->query.playFromStart());type.setOnAction(e->refresh());since.setOnAction(e->refresh());until.setOnAction(e->refresh());favorites.setOnAction(e->refresh());trash.setOnAction(e->refresh());
    browser.setOnDragOver(e->{if(e.getDragboard().hasFiles()){e.acceptTransferModes(TransferMode.COPY);e.consume();}});browser.setOnDragDropped(e->{if(e.getDragboard().hasFiles()){importPaths(e.getDragboard().getFiles().stream().map(File::toPath).toList());e.setDropCompleted(true);e.consume();}});
