  private void arrange(){arranging=true;try{panels.getItems().clear();Node items=mode.getValue()==Mode.TABLE?table:list;preview.setMinWidth(180);tree.setMinWidth(120);list.setMinWidth(180);table.setMinWidth(180);if(narrow){if(showNarrowPreview)panels.getItems().setAll(preview);else if(showNarrowFolders)panels.getItems().setAll(tree,items);else panels.getItems().setAll(items);if(panels.getDividers().size()==1)panels.setDividerPositions(.3);}else{panels.getItems().setAll(tree,items,preview);panels.setDividerPositions(firstDivider,secondDivider);for(int index=0;index<panels.getDividers().size();index++){final int k=index;panels.getDividers().get(index).positionProperty().addListener((o,a,b)->{if(!arranging&&!narrow){double[] p=panels.getDividerPositions();if(p.length==2&&p[0]>=.1&&p[0]<=.4&&p[1]>=p[0]+.15&&p[1]<=.85){firstDivider=p[0];secondDivider=p[1];schedulePreferences();}}});}}browser.setCenter(panels);}finally{arranging=false;}}
  private void refresh(){if(!unlocked())return;if(busy){refreshPending=true;return;}EncryptedArchive a=archive;long generation=++ticket;String term=search.getText(),selectedType=type.getValue(),parent=folder;boolean starred=favorites.isSelected(),deleted=trash.isSelected();Sort sorting=sort.getValue();long begin=since.getValue()==null?0:since.getValue().atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli(),end=until.getValue()==null?Long.MAX_VALUE:until.getValue().plusDays(1).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli()-1;
    worker.execute(()->{try{List<ArchiveEntry> all=a.entries(),found=a.search(new EncryptedArchive.Filter(term,parent,"Все типы".equals(selectedType)||selectedType==null?"":selectedType,begin,end,starred,deleted,true),EncryptedArchive.QUIET,()->closing||generation!=ticket);found=found.stream().sorted(switch(sorting==null?Sort.DATE:sorting){case NAME->Comparator.comparing(ArchiveEntry::name,String.CASE_INSENSITIVE_ORDER);case SIZE->Comparator.comparingLong(ArchiveEntry::size).reversed();case TYPE->Comparator.comparing(ArchiveEntry::type).thenComparing(ArchiveEntry::name);case DATE->Comparator.comparingLong(ArchiveEntry::addedAt).reversed();}).toList();final List<ArchiveEntry> sorted=found;long bytes=a.usedBytes(),limit=a.limit();int incomplete=a.incompleteIndexes();Platform.runLater(()->{if(closing||a!=archive||a.locked()||generation!=ticket)return;list.getItems().setAll(sorted);table.getItems().setAll(sorted);if(incomplete>0)status.setText("Не все PDF удалось включить в поиск; исходные файлы сохранены");else if(!a.backupPathAvailable())status.setText("Укажите папку автоматических копий на этом устройстве");usage.setText(size(bytes)+" / "+size(limit)+(bytes>limit*.9?" · Скоро будет достигнут лимит":""));if(tree.getRoot()==null)folders(all);});}catch(Exception failure){Platform.runLater(()->{if(!closing&&generation==ticket)status.setText(failure instanceof EncryptedArchive.IndexDamaged?failure.getMessage():"Не удалось прочитать архив");});}});
  }
  private void folders(List<ArchiveEntry> entries){var top=new TreeItem<>(new Folder("","Архив"));top.setExpanded(true);Map<String,TreeItem<Folder>> nodes=new HashMap<>();nodes.put("",top);for(var e:entries)if(e.directory()&&!e.trash())nodes.put(e.id(),new TreeItem<>(new Folder(e.id(),e.name())));for(var e:entries)if(nodes.containsKey(e.id()))nodes.getOrDefault(e.folder(),top).getChildren().add(nodes.get(e.id()));tree.setRoot(top);}
  private ContextMenu menu(ArchiveEntry e){ContextMenu m=new ContextMenu();MenuItem open=new MenuItem("Открыть"),rename=new MenuItem("Название и теги"),move=new MenuItem("Переместить"),favorite=new MenuItem(e.favorite()?"Убрать из избранного":"В избранное"),remove=new MenuItem(e.trash()?"Удалить окончательно":"В корзину");open.setOnAction(x->{previewId="";selected(e);});rename.setOnAction(x->edit(e));move.setOnAction(x->movePrompt(e));favorite.setOnAction(x->job("Сохранение…",()->{archive.metadata(e.id(),e.folder(),e.name(),e.tags(),!e.favorite());return true;},v->refresh()));remove.setOnAction(x->{if(e.trash()){if(confirm("Удалить объект окончательно? Резервные и экспортированные копии сохраняются."))job("Удаление…",()->{archive.purge(e.id());return true;},v->{preview.getChildren().clear();tree.setRoot(null);refresh();});}else job("Перемещение в корзину…",()->{archive.trash(e.id(),true);return true;},v->{preview.getChildren().clear();tree.setRoot(null);refresh();});});m.getItems().addAll(open,rename,move,favorite,remove);if(e.trash()){MenuItem restore=new MenuItem("Вернуть из корзины");restore.setOnAction(x->job("Восстановление…",()->{archive.trash(e.id(),false);return true;},v->{tree.setRoot(null);refresh();}));m.getItems().add(restore);}return m;}
  private void newFolder(){String name=askText("Новая папка","Название","");if(name!=null)job("Создание папки…",()->archive.folder(folder,name),e->{tree.setRoot(null);refresh();});}
  private void edit(ArchiveEntry e){InWindowDialog<Void>d=new InWindowDialog<>();d.initOwner(stage);d.setTitle("Название и теги");TextField name=new TextField(e.name()),tags=new TextField(String.join(", ",e.tags()));Button save=button("Сохранить",()->{List<String> labels=Arrays.stream(tags.getText().split(",")).map(String::strip).filter(x->!x.isBlank()).toList();job("Сохранение…",()->{archive.metadata(e.id(),e.folder(),name.getText(),labels,e.favorite());return true;},x->{d.close();tree.setRoot(null);refresh();});});d.getDialogPane().setContent(new VBox(10,name,tags,save));themes.apply(d.getDialogPane());d.show();}
  private void movePrompt(ArchiveEntry e){if(!unlocked())return;try{List<Folder> choices=new ArrayList<>();choices.add(new Folder("","Архив"));for(var f:archive.entries())if(f.directory()&&!f.trash())choices.add(new Folder(f.id(),f.name()));InWindowDialog<Void>d=new InWindowDialog<>();d.initOwner(stage);d.setTitle("Переместить");ComboBox<Folder> picker=new ComboBox<>(FXCollections.observableArrayList(choices));picker.setValue(choices.getFirst());d.getDialogPane().setContent(new VBox(10,picker,button("Переместить",()->{move(e.id(),picker.getValue().id());d.close();})));themes.apply(d.getDialogPane());d.show();}catch(IOException invalid){status.setText("Архив заблокирован");}}
