  private void importFiles(){InWindowFileChooser picker=new InWindowFileChooser();picker.setTitle("Добавить в архив");var selected=picker.showOpenMultipleDialog(stage);if(selected!=null)importPaths(selected.stream().map(File::toPath).toList());}
  Path location(){return location;}
  void importDownload(Path path){importPaths(List.of(path));}
  void importDownload(org.securemail.client.safeweb.SafeWebDownload.Snapshot snapshot){
    if(busy||closing||!unlocked()){try{snapshot.close();}catch(IOException ignored){}status.setText("Сначала завершите текущую операцию и разблокируйте архив");return;}
    job("Импорт загрузки…",()->{try(snapshot){try{archive.importFile(snapshot.path(),folder,false,this::progress,cancelled::get);return true;}catch(EncryptedArchive.Duplicate duplicate){return false;}}},added->{status.setText(added?"Загрузка зашифрована и добавлена в архив":"Такой файл уже есть в архиве");tree.setRoot(null);refresh();});
  }
  private void importPaths(List<Path> paths){if(paths.isEmpty()||!unlocked())return;List<Path> files=List.copyOf(paths);job("Добавление файлов…",()->{List<Path> duplicates=new ArrayList<>();for(Path p:files)try{archive.importFile(p,folder,false,this::progress,cancelled::get);}catch(EncryptedArchive.Duplicate duplicate){duplicates.add(p);}return duplicates;},dupes->{status.setText(dupes.isEmpty()?"Файлы добавлены":"Возможные дубликаты: "+dupes.size());tree.setRoot(null);refresh();if(!dupes.isEmpty()&&confirm("Такие файлы уже есть. Добавить отдельные копии без замены оригиналов?"))Platform.runLater(()->job("Добавление копий…",()->{for(Path p:dupes)archive.importFile(p,folder,true,this::progress,cancelled::get);return true;},x->refresh()));});}
  private void selected(ArchiveEntry e){if(e.id().equals(previewId))return;previewId=e.id();if(e.directory()){folder=e.id();refresh();return;}preview.getChildren().clear();showNarrowPreview=true;arrange();preview.getChildren().add(button("К списку",()->{showNarrowPreview=false;previewId="";arrange();}));if(e.trash()){preview.getChildren().add(new Label("Объект в корзине"));return;}Label title=new Label(e.name());title.getStyleClass().add("heading");title.setWrapText(true);HBox actions=new HBox(8,button("Экспорт",()->export(e,false)),button("Открыть внешне",()->export(e,true)));preview.getChildren().addAll(title,actions);if(!Set.of("letter","text","image","pdf").contains(e.type())){preview.getChildren().add(new Label("Используйте экспорт или внешнюю программу"));return;}
    job("Открытие файла…",()->{byte[] bytes=archive.previewBytes(e.id(),e.type().equals("text")||e.type().equals("letter")?ArchiveDocuments.MAX_TEXT:ArchiveDocuments.MAX_PREVIEW);try{return switch(e.type()){case "text","letter"->ArchiveDocuments.text(bytes);case "image"->ArchiveDocuments.imagePreview(bytes);default->ArchiveDocuments.pdf(bytes,0);};}finally{Arrays.fill(bytes,(byte)0);}},result->{if(result instanceof String text){TextArea area=new TextArea(text);area.setEditable(false);area.setWrapText(true);VBox.setVgrow(area,Priority.ALWAYS);preview.getChildren().add(area);}else if(result instanceof byte[] image){image(image);}else if(result instanceof ArchiveDocuments.PdfPage pdf){image(pdf.png());Label page=new Label("Страница 1 / "+pdf.pages());Button next=new Button("Далее"),back=new Button("Назад");int[] current={0};Runnable render=()->job("Открытие страницы…",()->{byte[] b=archive.previewBytes(e.id(),ArchiveDocuments.MAX_PREVIEW);try{return ArchiveDocuments.pdf(b,current[0]);}finally{Arrays.fill(b,(byte)0);}},p->{preview.getChildren().removeIf(n->n instanceof ImageView);image(p.png());page.setText("Страница "+(current[0]+1)+" / "+p.pages());});next.setOnAction(x->{if(current[0]+1<pdf.pages()){current[0]++;render.run();}});back.setOnAction(x->{if(current[0]>0){current[0]--;render.run();}});preview.getChildren().add(new HBox(8,back,page,next));}});
  }
  private void image(byte[] bytes){try{ImageView v=new ImageView(new Image(new ByteArrayInputStream(bytes)));v.setPreserveRatio(true);v.fitWidthProperty().bind(preview.widthProperty().subtract(28));v.fitHeightProperty().bind(preview.heightProperty().subtract(180));v.setSmooth(true);preview.getChildren().add(v);}finally{Arrays.fill(bytes,(byte)0);}}
  private void export(ArchiveEntry e,boolean external){if(!confirm(external?"Внешняя программа может создать незашифрованные копии и обработать активное содержимое. Экспортировать выбранный файл и открыть его?":"Будет создан обычный незашифрованный файл вне архива. Продолжить?"))return;InWindowFileChooser picker=new InWindowFileChooser();picker.setInitialFileName(e.name());File target=picker.showSaveDialog(stage);if(target==null)return;job("Экспорт…",()->{archive.export(e.id(),target.toPath(),this::progress,cancelled::get);if(external){if(!java.awt.Desktop.isDesktopSupported())throw new IOException("Внешнее открытие недоступно; файл экспортирован");java.awt.Desktop.getDesktop().open(target);}return true;},v->status.setText("Файл экспортирован"));}
  private void settings(){InWindowDialog<Void>d=new InWindowDialog<>();d.initOwner(stage);d.setTitle("Управление архивом");VBox panel=new VBox(12);panel.getChildren().addAll(button("Пароль и восстановление",this::security),button("Лимит и блокировка",this::limits),button("Создать резервную копию",this::backup),button("Автоматические копии",this::schedule),button("Восстановить отдельно",()->restore(false)),button("Объединить с копией",()->restore(true)),button("Перестроить индекс",()->job("Перестроение индекса…",()->{archive.rebuildIndex(this::progress,cancelled::get);return true;},v->refresh())),button("Проверить целостность",()->job("Проверка…",()->{archive.verifyAll(this::progress,cancelled::get);return true;},v->status.setText("Целостность проверена"))),button("Ремонт диагностической копии",this::repair));d.getDialogPane().setContent(panel);themes.apply(d.getDialogPane());d.show();}
  private void security(){InWindowDialog<Void> d=new InWindowDialog<>();d.initOwner(stage);d.setTitle("Пароль и восстановление");d.getDialogPane().setContent(new VBox(12,button("Изменить пароль",()->{char[] password=askSecret("Новый пароль архива",true);if(password!=null)job("Смена пароля…",()->{try{archive.changePassword(password);return true;}finally{Arrays.fill(password,'\0');}},v->status.setText("Пароль изменён. Старые копии сохраняют прежнюю защиту"));}),button("Новый ключ восстановления",()->{if(confirm("Заменить ключ восстановления? Прежний ключ перестанет открывать текущий архив; сохранённые копии не меняются."))job("Защита ключа…",()->archive.rotateRecovery(true),this::recoveryKey);}),button("Отключить восстановление",()->{if(confirm("Без пароля и ключа восстановления доступ будет утрачен. Отключить ключ текущего архива?"))job("Сохранение…",()->archive.rotateRecovery(false),v->status.setText("Восстановление ключом отключено для текущего архива"));})));themes.apply(d.getDialogPane());d.show();}

  private void recoveryKey(char[] key){InWindowDialog<Void>d=new InWindowDialog<>();d.initOwner(stage);d.setTitle("Ключ восстановления");TextArea value=new TextArea(new String(key));value.setEditable(false);value.setWrapText(true);value.setPrefRowCount(3);Label hint=new Label("Сохраните вне приложения. Ключ не хранится открытым текстом и не отправляется на сервер.");hint.setWrapText(true);d.getDialogPane().setContent(new VBox(10,hint,value,button("Сохранён",d::close)));d.onClose(()->{value.clear();Arrays.fill(key,'\0');});themes.apply(d.getDialogPane());d.show();}
  private void limits(){try{TextField size=new TextField(Long.toString(archive.limit()/1024/1024)),idle=new TextField(Integer.toString(archive.lockMinutes()));InWindowDialog<Void>d=new InWindowDialog<>();d.initOwner(stage);d.setTitle("Лимит и блокировка");d.getDialogPane().setContent(new VBox(10,new Label("Лимит, МБ"),size,new Label("Блокировать после бездействия, минут"),idle,button("Сохранить",()->{long bytes;int minutes;try{bytes=Math.multiplyExact(Long.parseLong(size.getText()),1024*1024);minutes=Integer.parseInt(idle.getText());}catch(RuntimeException invalid){status.setText("Введите корректные значения");return;}job("Сохранение…",()->{archive.settings(bytes,minutes);return true;},v->{d.close();refresh();});})));themes.apply(d.getDialogPane());d.show();}catch(IOException invalid){status.setText("Архив заблокирован");}}
  private void backup(){InWindowFileChooser picker=new InWindowFileChooser();picker.setInitialFileName("AEGIS-archive.aegis-archive");File file=picker.showSaveDialog(stage);if(file==null)return;boolean separate=confirm("Использовать отдельный пароль копии? Отмена оставляет защиту паролем архива.");char[] password=separate?askSecret("Пароль копии",true):null;if(separate&&password==null)return;job("Резервное копирование…",()->{try{archive.backup(file.toPath(),password,this::progress,cancelled::get);return true;}finally{if(password!=null)Arrays.fill(password,'\0');}},v->status.setText("Зашифрованная копия сохранена"));}
  private void schedule(){Path dir=new InWindowDirectoryChooser().choose(stage,"Локальная папка резервных копий");if(dir==null)return;String interval=askText("Автоматические копии","Интервал в минутах (0 — выключить)","1440");if(interval==null)return;long minutes;try{minutes=Long.parseLong(interval);}catch(NumberFormatException invalid){status.setText("Введите число минут");return;}boolean separate=confirm("Защитить автоматические копии отдельным паролем? Отмена использует пароль архива.");char[] secret=separate?askSecret("Пароль копии",true):null;if(separate&&secret==null)return;job("Сохранение расписания…",()->{try{archive.backupSchedule(dir,minutes,secret);return true;}finally{if(secret!=null)Arrays.fill(secret,'\0');}},v->status.setText("Копии создаются по расписанию, пока архив разблокирован"));}
  private void restore(boolean merge){if(merge&&!unlocked())return;InWindowFileChooser picker=new InWindowFileChooser();picker.setTitle("Зашифрованная копия архива");File file=picker.showOpenDialog(stage);if(file==null)return;char[] secret=askSecret("Пароль резервной копии",false);if(secret==null)return;if(merge&&!confirm("Проверить и объединить копию? Совпадающие файлы пропускаются, конфликты имён сохраняются отдельно; существующие файлы не перезаписываются.")){Arrays.fill(secret,'\0');return;}
    Path destination=profile.root().resolveSibling(profile.root().getFileName()+".archive-restored-"+UUID.randomUUID());job("Восстановление…",()->{try{EncryptedArchive other=ArchiveBackup.restore(file.toPath(),destination,guards(),secret,Clock.systemUTC(),this::progress,cancelled::get);if(merge){try(other){return archive.merge(other,false,this::progress,cancelled::get);}}return other;}finally{Arrays.fill(secret,'\0');}},value->{if(value instanceof EncryptedArchive restored){if(archive!=null){EncryptedArchive old=archive;old.requestLock();worker.execute(old::close);}archive=restored;location=restored.root();schedulePreferences();showBrowser();status.setText("Восстановлено отдельно: "+location.getFileName());}else{tree.setRoot(null);refresh();status.setText("Объединение завершено; диагностическая копия сохранена");}});
  }
  private void repair(){Path source=location,destination=profile.root().resolveSibling(profile.root().getFileName()+".archive-diagnostic-"+UUID.randomUUID());char[] secret=askSecret("Пароль архива для ремонта копии",false);if(secret==null)return;job("Создание и проверка диагностической копии…",()->{try{return EncryptedArchive.repairCopy(source,destination,guards(),secret,Clock.systemUTC(),this::progress);}finally{Arrays.fill(secret,'\0');}},value->{value.close();status.setText("Проверенная диагностическая копия сохранена. Оригинал не изменён.");});}
  private String askText(String title,String prompt,String initial){InWindowDialog<String>d=new InWindowDialog<>();d.initOwner(stage);d.setTitle(title);TextField f=new TextField(initial);f.setPromptText(prompt);d.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);d.getDialogPane().setContent(f);d.setResultConverter(b->b==ButtonType.OK?f.getText():null);themes.apply(d.getDialogPane());return d.showAndWait().orElse(null);}
  private char[] askSecret(String title,boolean repeat){InWindowDialog<char[]>d=new InWindowDialog<>();d.initOwner(stage);d.setTitle(title);PasswordField a=new PasswordField(),b=new PasswordField();a.setPromptText("Пароль");b.setPromptText("Повторите пароль");VBox p=new VBox(10,a);if(repeat)p.getChildren().add(b);d.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);d.getDialogPane().setContent(p);d.setResultConverter(x->{if(x!=ButtonType.OK)return null;if(repeat&&!a.getText().equals(b.getText())){status.setText("Пароли не совпадают");return null;}return a.getText().toCharArray();});themes.apply(d.getDialogPane());char[] result=d.showAndWait().orElse(null);a.clear();b.clear();return result;}
  void archiveMail(LocalStore.HistoryItem item,PlainMessage plain,String body,Runnable finished){
    if(!unlocked()||busy||closing){status.setText("Сначала создайте или разблокируйте архив в разделе «Архив»");finished.run();return;}
    job("Сохранение письма в архив…",()->{try{String title=plain.subject().replaceAll("[\\p{Cntrl}/\\\\]"," ").strip();if(title.isBlank())title="Письмо";ArchiveEntry folder=archive.folder("",title.substring(0,Math.min(200,title.length())));String text="От: "+item.packet().senderNickname()+"\nДата: "+date(item.time())+"\nТема: "+plain.subject()+"\n\n"+body;byte[] bytes=text.getBytes(StandardCharsets.UTF_8);try{archive.importBytes("Письмо.txt","letter",bytes,folder.id(),true,this::progress,cancelled::get);}finally{Arrays.fill(bytes,(byte)0);}for(var f:plain.files()){byte[] attachment=plain.attachmentBytes(f.name());try{archive.importBytes(f.name(),archiveType(f.name(),attachment),attachment,folder.id(),true,this::progress,cancelled::get);}finally{Arrays.fill(attachment,(byte)0);}}return true;}finally{Platform.runLater(finished);}},v->{tree.setRoot(null);status.setText("Защищённая копия сохранена в архив");refresh();});
  }
  private static String archiveType(String name,byte[] b){if(ArchiveDocuments.image(b))return "image";if(ArchiveDocuments.pdf(b))return "pdf";return name.toLowerCase(Locale.ROOT).endsWith(".txt")?"text":"file";}
  void lock(){lockEpoch++;EncryptedArchive old=archive;archive=null;ticket++;cancelled.set(true);if(old!=null){old.requestLock();worker.execute(old::close);}lockedPage();status.setText("Архив заблокирован");}
  private static String date(long time){return DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm").format(Instant.ofEpochMilli(time).atZone(ZoneId.systemDefault()));}
  private static String size(long size){return size>=1024L*1024*1024?String.format(Locale.ROOT,"%.2f ГБ",size/(1024.0*1024*1024)):size>=1024*1024?String.format(Locale.ROOT,"%.1f МБ",size/(1024.0*1024)):size>=1024?String.format(Locale.ROOT,"%.1f КБ",size/1024.0):size+" Б";}
  boolean awaitClosed(long seconds)throws InterruptedException{return worker.awaitTermination(seconds,TimeUnit.SECONDS);}
  @Override public void close(){if(closing)return;savePreferences();closing=true;lockEpoch++;ticket++;timer.stop();query.stop();persist.stop();cancelled.set(true);previewId="";search.clear();preview.getChildren().clear();list.getItems().clear();table.getItems().clear();tree.setRoot(null);EncryptedArchive old=archive;archive=null;if(old!=null){old.requestLock();worker.execute(old::close);}worker.shutdown();}
